<script setup>
import {applyTechnicalDefinition} from './technical-batch.js';
import {compositionThickness} from './technical-thickness.js';
import {printDocument} from "./printing.js";
import {ref,computed,watch} from 'vue';
const emit=defineEmits(['status-change']);
const frappe=window.frappe,api='mat_reco.material_reconfiguration.services.technical_study_service.';
const data=ref({studies:[],permissions:{}}),name=ref(''),lines=ref([]),activeId=ref(''),path=ref([]),busy=ref(false),error=ref(''),dirty=ref(false);
const checkedLineIds=ref([]),batchNotice=ref('');
const batchTargets=computed(()=>lines.value.filter(line=>checkedLineIds.value.includes(line.line_id)));
const canApplyDefinition=computed(()=>canWrite.value&&!busy.value&&active.value?.tree&&batchTargets.value.some(line=>line.line_id!==activeId.value));
function toggleAllLines(){checkedLineIds.value=batchTargets.value.length===lines.value.length?[]:lines.value.map(line=>line.line_id);}
function applyDefinition(){if(!canApplyDefinition.value)return;if(loose.value&&batchTargets.value.some(l=>Math.abs(Number(l.thickness_mm)-Number(active.value.thickness_mm))>.001)){frappe.msgprint("Choisir des types de même épaisseur pour partager cette composition.");return;}const count=applyTechnicalDefinition(lines.value,activeId.value,checkedLineIds.value);mark();batchNotice.value='Définition de '+active.value.repere+' appliquée à '+count+' autre(s) ouvrage(s). Enregistrer la fiche pour sauvegarder.';}
const study=computed(()=>data.value.study),dossier=computed(()=>data.value.chantier);
watch(()=>study.value?.docstatus,status=>emit('status-change',status??null),{immediate:true});
const active=computed(()=>lines.value.find(l=>l.line_id===activeId.value));
const canWrite=computed(()=>study.value?.docstatus===0&&data.value.permissions?.write);
const selected=computed(()=>{let node=active.value?.tree;for(const index of path.value)node=node?.children?.[index];return node;});
const inherited=computed(()=>{let node=active.value?.tree;for(const i of path.value){if(node?.mode==='existing')return true;node=node?.children?.[i];}return false;});
const editable=computed(()=>canWrite.value&&!inherited.value);
function nodeEditable(entry){
 if(!canWrite.value||entry.node.item_type!=='OUVRAGE')return false;
 let node=active.value?.tree;
 for(const i of entry.path){if(node?.mode==='existing')return false;node=node?.children?.[i];}
 return true;
}
function nodeWritable(entry){return nodeEditable(entry)&&entry.node.mode==='new';}
function addComponent(entry,kind='OUVRAGE'){
 if(kind==='Lame d’air'?!canWrite.value:!nodeEditable(entry))return;
 const lineId=activeId.value,target=entry.node,targetPath=[...entry.path];
 const dialog=new frappe.ui.Dialog({title:'Ajouter un composant à '+(target.item_name||displayCode(target)),fields:[
  {fieldname:'kind',label:'Type de composant',fieldtype:'Select',options:'OUVRAGE\nDECOUPE\nLame d’air',default:kind,reqd:1,onchange:()=>dialog.set_value('item','')},
  {fieldname:'item',label:'Article existant (facultatif)',fieldtype:'Link',options:'Item',description:'Laisser vide pour définir un nouvel article.',depends_on:'eval:doc.kind !== "Lame d’air"',get_query:()=>({filters:{custom_item_types:dialog.get_value('kind'),has_serial_no:1,disabled:0}})},
  {fieldname:'air_thickness',label:'Épaisseur de la lame d’air (mm)',fieldtype:'Float',depends_on:'eval:doc.kind === "Lame d’air"',mandatory_depends_on:'eval:doc.kind === "Lame d’air"'},
  {fieldname:'qty',label:'Quantité par ouvrage parent',fieldtype:'Int',default:1,reqd:1}
 ],primary_action_label:'Ajouter',primary_action:async function applyComponent(v){
  if(!Number.isInteger(Number(v.qty))||Number(v.qty)<=0){frappe.msgprint('Saisir une quantité entière positive.');return;}
  if(v.kind==='Lame d’air'){
   if(!(Number(v.air_thickness)>0)||!Number.isFinite(Number(v.air_thickness))){frappe.msgprint('Saisir une épaisseur de lame d’air positive.');return;}
   if(activeId.value!==lineId||!canWrite.value||!nodes.value.some(e=>e.node===target)){dialog.hide();return;}
   target.children||=[];target.children.push({mode:'air',item_type:'AIR',item_name:'Lame d’air',thickness_mm:Number(v.air_thickness),qty_factor:Number(v.qty),children:[]});path.value=[...targetPath,target.children.length-1];mark();dialog.hide();return;
  }
  if(target.mode==='existing'){
   frappe.confirm('Créer une variante de cet ouvrage pour modifier ses articles ?',()=>{if(activeId.value!==lineId||!nodeEditable(entry))return;path.value=[...targetPath];variant();applyComponent(v);});return;
  }
  dialog.disable_primary_action();
  try{
   const definition=v.item?await call('get_item_definition',{item_code:v.item}):null;
   if(activeId.value!==lineId||!nodeWritable(entry)||!nodes.value.some(e=>e.node===target))throw new Error('La sélection a changé. Recommencer l’ajout.');
   path.value=targetPath;add(v.kind);
   if(definition)Object.assign(selected.value,definition);
   selected.value.qty_factor=Number(v.qty);mark();dialog.hide();
  }catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}
 }});dialog.show();
}
function flatten(node,p=[],out=[]){if(!node)return out;out.push({node,path:p,key:p.join('.')||'root'});for(const [i,c] of (node.children||[]).entries())flatten(c,[...p,i],out);return out;}
const nodes=computed(()=>flatten(active.value?.tree));
const counts=computed(()=>({works:lines.value.length,pieces:dossier.value?.lines?.reduce((a,l)=>a+Number(l.qty||0),0)||0,newItems:lines.value.reduce((n,l)=>n+flatten(l.tree).filter(x=>x.node.mode==='new'&&x.node.item_type!=='AIR').length,0),missing:lines.value.filter(l=>(!loose.value&&(!l.length_mm||!l.width_mm))||!l.thickness_mm||flatten(l.tree).some(({node:n})=>n.item_type==='AIR'?!(Number(n.thickness_mm)>0):!(n.mode==='existing'?n.item_code:n.proposed_code)||(n.mode==='new'&&(!n.item_name||!n.stock_uom||!n.item_group||!n.warehouse))||(n.item_type==='OUVRAGE'&&!n.children?.length)||(n.item_type==='DECOUPE'&&n.children?.length!==1)||(n.item_type==='PRIMAIRE'&&(!n.length_mm||!n.width_mm||!n.thickness_mm)))).length}));
const calculatedThickness=computed(()=>compositionThickness(active.value?.tree));
const thicknessMismatch=computed(()=>calculatedThickness.value!==null&&Math.abs(calculatedThickness.value-Number(active.value?.thickness_mm||0))>0.001);
const loose=computed(()=>Number(dossier.value?.workflow_version||0)>=2);
const commonOperations=id=>JSON.parse(commercialType(id)?.common_extras||'[]');
const commercialType=id=>dossier.value?.work_types?.find(t=>t.type_id===id);
const typeQty=id=>(dossier.value?.lines||[]).filter(r=>r.work_type===id).reduce((n,r)=>n+Number(r.qty||0),0);
const macro=computed(()=>loose.value?{qty:typeQty(activeId.value)}:dossier.value?.lines?.find(l=>l.line_id===activeId.value));
const displayCode=(n)=>n?.item_type==='AIR'?'Lame d’air':n?.mode==='existing'?n.item_code:(n?.proposed_code||'Code à définir');
const sectionName=(id)=>data.value.sections?.find(s=>s.name===id)?.section_name||'Sans section';
async function call(method,args={},write=false){return(await frappe.call({method:api+method,args,type:write?'POST':'GET'})).message;}
function describe(e){try{return JSON.parse(JSON.parse(e._server_messages)[0]).message;}catch{return e.message||'Opération impossible.';}}
function migrateAir(node){for(const child of node.children||[])migrateAir(child);if(node.item_type==='OUVRAGE'&&Number(node.air_gap_mm)>0){node.children||=[];node.children.push({mode:'air',item_type:'AIR',item_name:'Lame d’air',thickness_mm:Number(node.air_gap_mm),qty_factor:1,children:[]});delete node.air_gap_mm;}return node;}
function apply(value){const sameStudy=data.value.study?.name===value.study?.name;checkedLineIds.value=sameStudy?checkedLineIds.value.filter(id=>(value.study?.lines||[]).some(line=>line.line_id===id)):[];batchNotice.value='';data.value=value;lines.value=(value.study?.lines||[]).map(l=>({...l,tree:migrateAir(JSON.parse(l.tree_json||'{}'))}));if(!lines.value.some(l=>l.line_id===activeId.value))activeId.value=lines.value[0]?.line_id||'';path.value=[];dirty.value=false;}
async function refresh(){busy.value=true;error.value='';try{apply(await call('get_study',{name:name.value||null}));}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function mark(){batchNotice.value='';dirty.value=true;}
function chooseLine(id){batchNotice.value='';activeId.value=id;path.value=[];}
async function save(){if(!canWrite.value)return;busy.value=true;error.value='';try{const value=await call('save_study',{name:name.value,modified:study.value.modified,notes:study.value.notes,lines:JSON.stringify(lines.value.map(l=>({...l,tree_json:JSON.stringify(l.tree)})))},true);apply(value);return true;}catch(e){error.value=describe(e);return false;}finally{busy.value=false;}}
function submit(){frappe.confirm('Valider la fiche et créer les Items manquants ? Les articles compatibles seront réutilisés. Aucune fabrication ne sera déclenchée.',async()=>{if(dirty.value&&!(await save()))return;busy.value=true;error.value='';try{await frappe.call({method:'frappe.client.submit',args:{doc:study.value}});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
function pick(field,doctype,filters={}){if(!editable.value)return;const dialog=new frappe.ui.Dialog({title:doctype,fields:[{fieldname:'value',label:doctype,fieldtype:'Link',options:doctype,reqd:1,get_query:()=>({filters})}],primary_action_label:'Choisir',async primary_action(v){dialog.disable_primary_action();try{if(field==='item_code'){const ratio=selected.value.qty_factor||1;const node=await call('get_item_definition',{item_code:v.value});Object.assign(selected.value,node,{qty_factor:ratio});}else{selected.value[field]=v.value;}mark();dialog.hide();}catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}}});dialog.show();}
function chooseItem(){const kind=selected.value.item_type;pick('item_code','Item',{custom_item_types:kind,disabled:0,...(['OUVRAGE','DECOUPE','PRIMAIRE'].includes(kind)?{has_serial_no:1}:{})});}
function variant(){selected.value.mode='new';selected.value.proposed_code='';mark();}
function add(kind){if(!editable.value||selected.value.mode!=='new')return;const node={mode:'new',proposed_code:'',item_name:'',item_type:kind,stock_uom:active.value.tree.stock_uom||'',item_group:'',warehouse:'',qty_factor:1,children:[]};selected.value.children||=[];selected.value.children.push(node);path.value=[...path.value,selected.value.children.length-1];mark();}
function blankTree(source=macro.value){return {mode:'new',proposed_code:'',item_name:source?.designation||'',item_type:'OUVRAGE',stock_uom:source?.uom||'',item_group:'',qty_factor:1,children:[]};}
function resetStudy(){if(!canWrite.value)return;frappe.confirm('Effacer les compositions de tous les ouvrages et reprendre toute la fiche ?',()=>{if(!canWrite.value)return;for(const line of lines.value){const source=loose.value?commercialType(line.line_id):dossier.value.lines.find(r=>r.line_id===line.line_id);line.tree=blankTree(source);line.length_mm=source?.length_mm||0;line.width_mm=source?.width_mm||0;line.thickness_mm=source?.thickness_mm||0;}study.value.notes='';path.value=[];mark();});}
function resetComposition(){if(!canWrite.value)return;frappe.confirm('Effacer toute la composition de cet ouvrage et la reprendre à zéro ?',()=>{if(!canWrite.value)return;active.value.tree=blankTree();path.value=[];mark();});}
function removeEntry(entry){if(!canWrite.value||busy.value)return;path.value=[...entry.path];if(entry.path.length)remove();else resetComposition();}
function remove(){
 if(!canWrite.value||!path.value.length)return;
 const target=selected.value,line=active.value,indices=[...path.value];
 frappe.confirm(target.item_type==='AIR'?'Retirer cette lame d’air ?':'Retirer cet article et tous ses enfants ? Les parents existants concernés deviendront des variantes à compléter avec de nouveaux codes.',()=>{
  if(!canWrite.value||active.value!==line||selected.value!==target)return;
  const p=[...indices],index=p.pop();let parent=line.tree;
  for(const i of [...p,null]){
   if(target.item_type!=='AIR'&&parent.mode==='existing'){parent.mode='new';parent.proposed_code='';}
   if(i!==null)parent=parent.children[i];
  }
  parent.children.splice(index,1);path.value=p;mark();
 });
}
function deleteStudy(){frappe.confirm('Supprimer définitivement cette fiche et sa composition ? Vous pourrez préparer une nouvelle fiche depuis le chantier.',async()=>{
 busy.value=true;error.value='';try{const chantier=await call('delete_study',{name:study.value.name,modified:study.value.modified},true);sessionStorage.setItem('univers-chantier-selected',chantier);frappe.set_route('chantiers');}catch(e){error.value=describe(e);}finally{busy.value=false;}
});}
function cancelStudy(){frappe.confirm('Annuler cette fiche validée ?',async()=>{busy.value=true;error.value='';try{await frappe.call({method:'frappe.client.cancel',args:{doctype:'Chantier Technical Study',name:study.value.name}});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
function show(){document.body.classList.remove('ug-technical-active');name.value=frappe.get_route()[1]||sessionStorage.getItem('univers-technical-study')||'';sessionStorage.removeItem('univers-technical-study');refresh();}
function hide(){}
function back(){const leave=()=>{sessionStorage.setItem('univers-chantier-selected',dossier.value.name);frappe.set_route('chantiers');};if(dirty.value)frappe.confirm('Quitter sans enregistrer les modifications techniques ?',leave);else leave();}
defineExpose({show,hide});
</script>
<template>
<div class="ug-tech">
 <header><section class="toolbar"><label><select aria-label="Fiche technique" v-model="name" :disabled="busy||dirty" @change="refresh"><option value="">Sélectionner une fiche</option><option v-for="s in data.studies" :key="s.name" :value="s.name">{{s.chantier}} · {{s.name}} · {{['Brouillon','Validée','Annulée'][s.docstatus]}}</option></select></label><button v-if="study" @click="frappe.set_route('Form','Chantier Technical Study',study.name)">Document ERPNext</button></section><div class="actions"><button v-if="study" :disabled="busy||dirty" title="Enregistrer les modifications avant impression" @click="printDocument('Chantier Technical Study',study.name)">Imprimer A4</button><button v-if="dossier" @click="back">← Retour au chantier</button><button :disabled="busy" @click="refresh">Actualiser</button><button v-if="study?.docstatus===1&&data.permissions?.cancel" :disabled="busy||dirty" @click="cancelStudy">Annuler la fiche</button><button v-if="study&&study.docstatus!==1&&data.permissions?.delete" class="danger" :disabled="busy" @click="deleteStudy">Supprimer la fiche</button><button v-if="canWrite" class="danger" :disabled="busy" @click="resetStudy">Reprendre toute la fiche</button><button v-if="canWrite" class="blue" :disabled="busy||!dirty" @click="save">Enregistrer</button><button v-if="canWrite&&data.permissions?.submit" class="green" :disabled="busy||data.stale" @click="submit">Valider la fiche</button></div></header>
 <div v-if="error" class="alert" role="alert" v-text="error"></div><div v-if="data.stale" class="alert">Les besoins commerciaux ont changé. Préparer une nouvelle fiche depuis le chantier avant validation.</div>
 <template v-if="study">
 <section class="cards"><article><strong>{{counts.works}}</strong><span>{{loose?"types à définir":"ouvrages à étudier"}}</span></article><article><strong>{{counts.pieces}}</strong><span>pièces prévues</span></article><article><strong>{{counts.newItems}}</strong><span>nouvelles définitions d’articles</span></article><article class="orange"><strong>{{counts.missing}}</strong><span>ouvrages à compléter</span></article></section>
 <div class="columns"><aside class="panel works"><h2>{{loose?'Types d’ouvrage à définir':'Ouvrages à étudier'}}</h2><div v-if="canWrite" class="batch-selection"><label><input type="checkbox" :checked="!!lines.length&&batchTargets.length===lines.length" :indeterminate="!!batchTargets.length&&batchTargets.length<lines.length" :disabled="busy" aria-label="Sélectionner tous les ouvrages à étudier" @change="toggleAllLines" /> Tout sélectionner</label><span>{{batchTargets.length}} ouvrage(s) coché(s)</span></div><div v-for="line in lines" :key="line.line_id" class="work-entry" :class="{checked:checkedLineIds.includes(line.line_id),selected:activeId===line.line_id}"><input v-if="canWrite" v-model="checkedLineIds" type="checkbox" :value="line.line_id" :disabled="busy" :aria-label="'Sélectionner '+line.repere+' pour la définition commune'" /><button :class="{selected:activeId===line.line_id}" :disabled="busy" @click="chooseLine(line.line_id)"><strong>{{line.repere}} · {{loose?'':dossier.lines.find(l=>l.line_id===line.line_id)?.designation}}</strong><small v-if="!loose">{{sectionName(dossier.lines.find(l=>l.line_id===line.line_id)?.section)}}</small><span v-if="loose">{{line.thickness_mm}} mm · {{typeQty(line.line_id)}} pièces liées</span><span v-else>{{line.length_mm||'—'}} × {{line.width_mm||'—'}} mm · {{dossier.lines.find(l=>l.line_id===line.line_id)?.qty}} pièces</span></button></div></aside>
 <main v-if="active" class="panel definition"><h2>{{active.repere}} — Définition technique</h2><div v-if="canWrite&&batchTargets.length" class="batch-definition"><p>Source : {{active.repere}} · Composition et épaisseur</p><button type="button" class="blue" :disabled="!canApplyDefinition" @click="applyDefinition">Appliquer cette définition aux {{batchTargets.length}} ouvrage(s) coché(s)</button></div><p v-if="batchNotice" class="batch-notice" role="status">{{batchNotice}}</p><div class="fields"><label v-if="!loose">Longueur (mm)<input v-model.number="active.length_mm" type="number" min="1" :disabled="!canWrite" @input="mark" /></label><label v-if="!loose">Hauteur (mm)<input v-model.number="active.width_mm" type="number" min="1" :disabled="!canWrite" @input="mark" /></label><label>Épaisseur totale (mm)<input v-model.number="active.thickness_mm" type="number" min="0.01" step="any" :disabled="!canWrite||loose" @input="mark" /></label><label>Quantité commerciale<input :value="macro?.qty" disabled /></label></div>
 <div v-if="calculatedThickness!==null" class="thickness-check" :class="{invalid:thicknessMismatch}" role="status">Épaisseur calculée : {{calculatedThickness}} mm. <strong v-if="thicknessMismatch">L’épaisseur totale saisie doit être égale à {{calculatedThickness}} mm.</strong><span v-else>Cohérente.</span></div>
 <div v-if="loose&&commonOperations(active.line_id).length" class="thickness-check"><strong>Services / accessoires commerciaux communs :</strong><span v-for="extra in commonOperations(active.line_id)" :key="extra.key"> {{extra.item_code}} · coefficient {{extra.factor||1}} ; </span></div>
 <h3>Composition de fabrication</h3><button v-if="canWrite" class="danger" :disabled="busy" @click="resetComposition">Reprendre toute la composition</button>
 <div class="tree"><template v-for="entry in nodes" :key="entry.key"><div class="tree-node" :style="{marginLeft:entry.path.length*16+'px'}">
 <div class="node-card" :class="{selected:path.join('.')===entry.path.join('.'),'air-layer':entry.node.item_type==='AIR'}"><button class="node-select" :class="{selected:path.join('.')===entry.path.join('.')}" @click="path=entry.path"><span class="icon">{{entry.node.item_type==='AIR'?'≋':entry.node.item_type==='PRIMAIRE'?'▱':entry.node.item_type==='DECOUPE'?'▯':'◇'}}</span><span><strong>{{entry.node.item_name||displayCode(entry.node)}}</strong><small>{{displayCode(entry.node)}} · {{entry.node.item_type==='AIR'?entry.node.thickness_mm+' mm':entry.node.item_type}} <template v-if="entry.path.length">· × {{entry.node.qty_factor||1}}</template></small></span><span v-if="entry.node.item_type==='OUVRAGE'" class="component-count">{{entry.node.children?.length||0}} composant(s)</span><span class="tag" :class="entry.node.mode==='existing'?'valid':'new'">{{entry.node.item_type==='AIR'?'Lame d’air':entry.node.mode==='existing'?'Item existant':'À créer'}}</span></button>
 <button v-if="canWrite" :disabled="busy" class="node-delete" :aria-label="'Supprimer '+(entry.node.item_name||displayCode(entry.node))+' et ses enfants'" title="Supprimer ce composant et ses enfants" @click="removeEntry(entry)"><svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7" /></svg></button>
 <button v-if="canWrite&&entry.node.item_type==='OUVRAGE'" :disabled="!nodeEditable(entry)" class="node-add" :aria-label="'Ajouter un composant à '+(entry.node.item_name||displayCode(entry.node))" title="Ajouter un composant" @click="addComponent(entry)">+</button></div>
 </div></template></div>
 <div v-if="editable&&selected?.mode==='new'&&selected.item_type==='DECOUPE'&&!selected.children?.length" class="actions"><button @click="add('PRIMAIRE')">+ Matière primaire</button></div>
 <label class="notes">Notes techniques<textarea v-model="study.notes" :disabled="!canWrite" @input="mark"></textarea></label></main>
 <aside v-if="selected" class="panel inspector"><h2>Article et contrôles</h2><div class="actions" v-if="editable&&selected.item_type!=='AIR'"><button @click="chooseItem">Rechercher un Item existant</button><button v-if="selected.mode==='existing'" @click="variant">Définir un nouvel article</button></div>
 <template v-if="selected.item_type==='AIR'"><label>Type de composant<input value="Lame d’air" disabled /></label><label>Épaisseur de la lame d’air (mm)<input v-model.number="selected.thickness_mm" type="number" min="0.01" step="any" :disabled="!canWrite" @input="mark" /></label><label>Quantité par parent<input v-model.number="selected.qty_factor" type="number" min="1" step="1" :disabled="!canWrite" @input="mark" /></label></template><template v-else>
 <label>Type d’article<select v-model="selected.item_type" :disabled="!editable||selected.mode==='existing'" @change="mark"><option>OUVRAGE</option><option>DECOUPE</option><option v-if="path.length">PRIMAIRE</option><option v-if="selected.mode==='existing'&&selected.item_type==='ACCESSOIRE'">ACCESSOIRE</option></select></label>
 <label>{{selected.mode==='existing'?'Code article existant':'Code article proposé'}}<input v-if="selected.mode==='new'" v-model="selected.proposed_code" :disabled="!editable" @input="mark" /><input v-else :value="selected.item_code" disabled /></label><label>Désignation<input v-model="selected.item_name" :disabled="!editable||selected.mode==='existing'" @input="mark" /></label>
 <div class="fields"><label>Unité<button :disabled="!editable||selected.mode==='existing'" @click="pick('stock_uom','UOM')">{{selected.stock_uom||'Choisir'}}</button></label><label>Groupe d’articles<button :disabled="!editable||selected.mode==='existing'" @click="pick('item_group','Item Group',{is_group:0})">{{selected.item_group||'Choisir'}}</button></label></div>
 <label v-if="path.length">Quantité par parent<input v-model.number="selected.qty_factor" type="number" min="1" step="1" :disabled="!editable" @input="mark" /></label>
 <template v-if="selected.item_type==='PRIMAIRE'"><h3>Format nominal de la plaque</h3><div class="fields"><label>Longueur (mm)<input v-model.number="selected.length_mm" type="number" :disabled="!editable||selected.mode==='existing'" @input="mark" /></label><label>Hauteur (mm)<input v-model.number="selected.width_mm" type="number" :disabled="!editable||selected.mode==='existing'" @input="mark" /></label><label>Épaisseur (mm)<input v-model.number="selected.thickness_mm" type="number" step="any" :disabled="!editable||selected.mode==='existing'" @input="mark" /></label></div></template>
